#include "master_test_access.hpp"
#include <fstream>
#include <iostream>
#include <cstring>
#include <stdexcept>
#include <vector>
using namespace mfrk::master;
class Reader {std::vector<std::uint8_t> d;std::size_t p=0;public:explicit Reader(const char*path){std::ifstream f(path,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("open");auto n=f.tellg();if(n<12||n>2*1024*1024)throw std::runtime_error("size");d.resize(static_cast<std::size_t>(n));f.seekg(0);if(!f.read(reinterpret_cast<char*>(d.data()),n))throw std::runtime_error("read");}template<class T>T read(){T x;if(sizeof x>d.size()-p)throw std::runtime_error("truncated");std::memcpy(&x,d.data()+p,sizeof x);p+=sizeof x;return x;}void end(){if(p!=d.size())throw std::runtime_error("trailing");}};
int main(int argc,char**argv)try{if(argc!=2)return 2;Reader r(argv[1]);if(r.read<std::array<char,8>>()!=std::array<char,8>{'M','A','S','T','0','0','0','1'})return 2;DelayMemory memory;for(auto&row:memory.samples)for(auto&x:row)x=std::bit_cast<float>(r.read<std::uint32_t>());auto master=Master::admitted_ready_owner(memory);auto count=r.read<std::uint32_t>();if(!count||count>10000)return 2;std::uint64_t errors=0,state=0,rings=0,counters=0,smoothing=0;
for(unsigned n=0;n<count;++n){const auto dirty=r.read<std::array<std::uint8_t,3>>();for(auto b:dirty)if(b>1)return 2;const auto pre=std::bit_cast<float>(r.read<std::uint32_t>()),post=std::bit_cast<float>(r.read<std::uint32_t>());const auto mono=r.read<std::uint16_t>();const auto reset=r.read<std::uint8_t>();if(reset>1)return 2;if(dirty[0])master.set_prepared_pre_gain(pre);if(dirty[1])master.set_prepared_post_gain(post);if(dirty[2])master.set_mono(mono>0x7ffd);if(reset)master.reset();StereoBlock input{},output{};for(auto&row:input)for(auto&x:row)x=std::bit_cast<float>(r.read<std::uint32_t>());const auto expected=r.read<std::array<std::uint32_t,32>>();const auto ls=r.read<std::array<std::uint32_t,4>>();const auto cursor=r.read<std::array<std::uint32_t,6>>();const auto ring=r.read<std::array<std::uint32_t,290>>();const auto ss=r.read<std::array<std::uint32_t,4>>();const auto gain=r.read<std::array<std::uint32_t,16>>();master.process(input,output);const auto&l=MasterTestAccess::limiter(master);
for(unsigned ch=0;ch<2;++ch){for(unsigned i=0;i<16;++i)errors+=std::bit_cast<std::uint32_t>(output[ch][i])!=expected[ch*16+i];state+=std::bit_cast<std::uint32_t>(LimiterTestAccess::peak(l)[ch])!=ls[ch];state+=std::bit_cast<std::uint32_t>(LimiterTestAccess::gain_db(l)[ch])!=ls[ch+2];counters+=LimiterTestAccess::valid(l)[ch]!=cursor[ch*3];counters+=cursor[ch*3+1]!=145;counters+=LimiterTestAccess::write(l)[ch]!=cursor[ch*3+2];for(unsigned i=0;i<145;++i)rings+=std::bit_cast<std::uint32_t>(memory.samples[ch][i])!=ring[ch*145+i];}for(unsigned i=0;i<4;++i)smoothing+=MasterTestAccess::smoother(master)[i]!=ss[i];for(unsigned i=0;i<16;++i)smoothing+=std::bit_cast<std::uint32_t>(MasterTestAccess::gains(master)[i])!=gain[i];
}
r.end();std::cout<<"blocks "<<count<<" output "<<errors<<" limiter_state "<<state<<" counters "<<counters<<" rings "<<rings<<" smoother "<<smoothing<<"\n";return errors||state||counters||rings||smoothing?1:0;
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}
